//! World 2026-27: downloaded into the cache (D8) and checked against the upstream pin
//! (docs/PLAN.md §5.2). Its data is the SWOS 96/97 Mod's: never committed.

use std::path::{Path, PathBuf};

use openswos_test_utils::cache::{WORLD_2627_PACKAGE, fetch};
use openswos_world_package_resource::{
    Fingerprint, OpenedPackage, POOL_FILE, PackageFiles, TEAMS_FOLDER, WorldPackage,
};

use crate::error::ExtractError;

/// World 2026-27's baked tables in the upstream checkout (generated by
/// scripts/world_import.py): it states the fingerprint of the data the pin was built with, and
/// names the world's cups.
pub(crate) const WORLD_DATA_SOURCE: &str = "src/world_data.c";

/// The function of [`WORLD_DATA_SOURCE`] that returns the fingerprint (upstream
/// `World_DataFingerprint` answers with it in World 2026-27).
const FINGERPRINT_FUNCTION: &str = "WorldData2627_DataFingerprint";

/// What precedes the fingerprint in that function: its first string return.
const STRING_RETURN: &str = "return \"";

/// What ends a C string.
const QUOTE: char = '"';

/// World 2026-27's package, downloaded and checked.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Fetched {
    /// The zip in the cache.
    pub zip: PathBuf,
    /// The package, opened.
    pub opened: OpenedPackage,
    /// Its foreign players' pool as it holds it (`teams/POOLPLYR.DAT`, RNC-packed: the
    /// package does not read it, D9), if it has one.
    pub packed_pool: Option<Vec<u8>>,
}

/// World 2026-27's package: downloaded once into `target/cache/downloads/` (its checksum
/// checked there), then its `WORLD.ini` fingerprint checked against its files and against
/// the pin's, read from the upstream checkout in `checkout`.
///
/// # Errors
///
/// When the checkout states no fingerprint, the download fails, the package does not open,
/// or a fingerprint does not match ([`ExtractError::OutOfStep`]: the package and the pin are
/// out of step).
pub fn world_2627(checkout: &Path) -> Result<Fetched, ExtractError> {
    let pin = pinned_fingerprint(checkout)?;
    let zip =
        fetch(&WORLD_2627_PACKAGE).map_err(|skip| ExtractError::Download(skip.to_string()))?;
    let file = std::fs::File::open(&zip).map_err(|source| ExtractError::Read {
        path: zip.clone(),
        source,
    })?;
    let files = PackageFiles::read_zip(std::io::BufReader::new(file))?;
    let opened = WorldPackage::from_files(&files)?;
    check_against_pin(&opened, &pin)?;
    let packed_pool = files
        .get(&format!("{TEAMS_FOLDER}/{POOL_FILE}"))
        .map(<[u8]>::to_vec);
    Ok(Fetched {
        zip,
        opened,
        packed_pool,
    })
}

/// The fingerprint of the World 2026-27 data the upstream checkout in `checkout` was built
/// with.
///
/// # Errors
///
/// When the checkout's [`WORLD_DATA_SOURCE`] does not read or states none.
pub fn pinned_fingerprint(checkout: &Path) -> Result<Fingerprint, ExtractError> {
    let path = checkout.join(WORLD_DATA_SOURCE);
    let text = std::fs::read_to_string(&path).map_err(|source| ExtractError::Read {
        path: path.clone(),
        source,
    })?;
    text.split_once(FINGERPRINT_FUNCTION)
        .and_then(|(_, body)| body.split_once(STRING_RETURN))
        .and_then(|(_, rest)| rest.split_once(QUOTE))
        .and_then(|(fingerprint, _)| Fingerprint::try_from(fingerprint.to_owned()).ok())
        .ok_or(ExtractError::NoPinnedFingerprint {
            path,
            function: FINGERPRINT_FUNCTION,
        })
}

/// Checks that `opened` states its files' fingerprint, and that it is `pin`.
///
/// # Errors
///
/// [`ExtractError::FingerprintMismatch`] or [`ExtractError::OutOfStep`].
pub fn check_against_pin(opened: &OpenedPackage, pin: &Fingerprint) -> Result<(), ExtractError> {
    let check = &opened.fingerprint;
    if !check.is_match() {
        return Err(ExtractError::FingerprintMismatch {
            stated: check.stated.clone(),
            computed: check.computed.clone(),
        });
    }
    if &check.stated != pin {
        return Err(ExtractError::OutOfStep {
            package: check.stated.clone(),
            pin: pin.clone(),
        });
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use openswos_test_utils::world_1996_97_path;
    use openswos_world_package_resource::{PackageFiles, WORLD_INI};

    use super::*;
    use crate::assemble::committed;

    /// The fingerprint function as upstream generates it, at the pin of 2026-11-21.
    const UPSTREAM_SNIPPET: &str = "const char *WorldData2627_DataFingerprint(void)\n{\n    \
        switch (World_Current()) {\n#if SWOS_WORLDS\n    case WORLD_2627:\n        \
        return \"80e20cdd3e92ec9c\";\n#endif\n    default:\n        return \"\";\n    }\n}\n";

    fn checkout_with(source: &str) -> tempfile::TempDir {
        let dir = tempfile::tempdir().expect("a temp dir");
        std::fs::create_dir(dir.path().join("src")).expect("src/");
        std::fs::write(dir.path().join(WORLD_DATA_SOURCE), source).expect("the source");
        dir
    }

    fn fingerprint(text: &str) -> Fingerprint {
        Fingerprint::try_from(text.to_owned()).expect("a fingerprint")
    }

    #[test]
    fn the_pin_states_its_fingerprint_in_the_generated_tables() {
        let checkout = checkout_with(UPSTREAM_SNIPPET);
        assert_eq!(
            pinned_fingerprint(checkout.path()).expect("the pin's"),
            fingerprint("80e20cdd3e92ec9c")
        );
    }

    #[test]
    fn a_checkout_without_it_is_named() {
        let checkout = checkout_with("int main(void) { return 0; }\n");
        let error = pinned_fingerprint(checkout.path()).expect_err("no function");
        assert!(error.to_string().contains(FINGERPRINT_FUNCTION), "{error}");
        let empty = tempfile::tempdir().expect("a temp dir");
        let error = pinned_fingerprint(empty.path()).expect_err("no file");
        assert!(error.to_string().contains("world_data.c"), "{error}");
    }

    /// A package as written: its `WORLD.ini` states its files' fingerprint.
    fn written() -> PackageFiles {
        committed(&world_1996_97_path())
            .expect("the committed package")
            .to_files()
            .expect("written")
    }

    #[test]
    fn a_package_must_state_its_files_and_be_the_pins() {
        let files = written();
        let opened = WorldPackage::from_files(&files).expect("a package");
        let own = opened.fingerprint.computed.clone();
        check_against_pin(&opened, &own).expect("in step");
        let error =
            check_against_pin(&opened, &fingerprint("0123456789abcdef")).expect_err("another pin");
        assert!(matches!(error, ExtractError::OutOfStep { .. }));
        assert!(error.to_string().contains("out of step"), "{error}");
    }

    #[test]
    fn a_package_stating_another_fingerprint_is_refused() {
        let mut files = written();
        let ini = String::from_utf8(files.get(WORLD_INI).expect("an ini").to_vec()).expect("text");
        let (head, _) = ini
            .split_once("fingerprint = ")
            .expect("a fingerprint line");
        files
            .insert(
                WORLD_INI,
                format!("{head}fingerprint = 0123456789abcdef\n").into_bytes(),
            )
            .expect("a safe path");
        let opened = WorldPackage::from_files(&files).expect("a package");
        let error = check_against_pin(&opened, &fingerprint("0123456789abcdef"))
            .expect_err("not its files'");
        assert!(matches!(error, ExtractError::FingerprintMismatch { .. }));
    }
}
